Design Engineering Tip: Don’t move objects at a constant shape. As speed increases, stretch them in the direction of travel. The faster they move, the more they deform. Combined with easing and subtle motion blur, even simple animations can feel significantly more dynamic.

const x = useMotionValue(0)
const v = useVelocity(x)

const scaleX = useTransform(v, [-1200, 0, 1200], [1.8, 1, 1.8])
const blur = useTransform(v, [-1200, 0, 1200], [3, 0, 3])

<motion.div
  animate={{ x: target }}
  style={{
    x,
    scaleX,
    filter: useTransform(blur, b => `blur(${b}px)`),
  }}
/>

